/* shadow around header */
.header__container{
	padding-top:0.5rem;	
padding-bottom:0.5rem;
box-shadow: 0px 8px 24px rgba(149, 149, 149, 0.2);
  border-radius: 50px;
}

.header.transparent .header__container {
	background:white;
}

.category-label {
	letter-spacing:0.1rem;
}

.post-card__body {
	text-align:center;
}

